import{_ as i,o as a,c as s,a0 as t}from"./chunks/framework.DPd3ST4h.js";const u=JSON.parse('{"title":"Review performance benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"performance-benchmark.md","filePath":"performance-benchmark.md","lastUpdated":1792860885000}'),n={name:"performance-benchmark.md"};function r(o,e,l,p,d,c){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="review-performance-benchmark" tabindex="-1">Review performance benchmark <a class="header-anchor" href="#review-performance-benchmark" aria-label="Permalink to &quot;Review performance benchmark&quot;">​</a></h1><p>Redline has a fixed 20-file performance corpus under <code>benchmark/performance/v1/</code>. It measures the bounded per-file review scheduler before later performance-epic changes to caching, indexing, prompts, or model execution.</p><p>The corpus contains:</p><ul><li>six ordinary TypeScript files;</li><li>four TypeScript test files;</li><li>three configuration files;</li><li>three documentation files;</li><li>two large TypeScript files;</li><li>two generated-like JSON artifacts.</li></ul><p>Every change is intentionally clean. A run fails its quality gate if any file is omitted, produces invalid output, produces a finding, loses required coverage, or fails publication through the forge-neutral publication service.</p><h2 id="run-the-recorded-baseline" tabindex="-1">Run the recorded baseline <a class="header-anchor" href="#run-the-recorded-baseline" aria-label="Permalink to &quot;Run the recorded baseline&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmark:performance</span></span></code></pre></div><p>The command rebuilds Redline, runs the fixed corpus through the production bundle loader, prompt builder, harness contract, result validator, output writer, PR-level contract, and publication service, then writes:</p><ul><li><code>benchmark/performance/v1/baseline/report.json</code></li><li><code>benchmark/performance/v1/baseline/report.md</code></li></ul><p>Recorded mode performs no network requests. It uses checked-in per-file model durations and bounded timing samples from named production Action runs. The report marks the SLO gate as <strong>not eligible</strong> because recorded data cannot prove current live latency.</p><p>The baseline uses four workers and largest-diff-first scheduling. It retains 1,208 seconds of total modeled model work and models 340 seconds of review wall time. The previous sequential baseline reported 1,260.8 seconds warm-index p95 and 1,474.3 seconds cold-index p95. The four-worker baseline reports 392.8 seconds warm and 606.3 seconds cold. Both are below the epic targets, but the report remains SLO-ineligible until at least five current live fixed-corpus runs pass the quality gate.</p><h2 id="run-an-opt-in-live-capture" tabindex="-1">Run an opt-in live capture <a class="header-anchor" href="#run-an-opt-in-live-capture" aria-label="Permalink to &quot;Run an opt-in live capture&quot;">​</a></h2><p>A live capture uses the pinned profile:</p><ul><li>Pi;</li><li>OpenRouter&#39;s OpenAI-compatible endpoint;</li><li><code>z-ai/glm-5.3-flash</code>;</li><li>CGC 0.5.7 context;</li><li>bounded parallel execution with four workers.</li></ul><p>Run at least five fixed-corpus repetitions to make the SLO gate eligible. This minimum applies to benchmark executions, not to the number of historical workflow-stage samples in each cache condition:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDLINE_LIVE_BENCHMARK</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDLINE_HARNESS=pi </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDLINE_MODEL_CONFIG=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{&quot;provider&quot;:&quot;openrouter&quot;,&quot;endpoint&quot;:&quot;https://openrouter.ai/api/v1&quot;,&quot;model&quot;:&quot;z-ai/glm-5.3-flash&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDLINE_MODEL_AUTH=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{&quot;openrouter&quot;:&quot;...&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mise </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmark:performance-live</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --runs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/redline-performance-live</span></span></code></pre></div><p>The live output path is mandatory. Live reports use owner-only file permissions. The selected credential and endpoint credential value are never written to the report.</p><p>The warm-index target is p95 at or below 10 minutes. The cold-index target is p95 at or below 15 minutes. The warm condition represents a validated exact-base cache hit and therefore requires <code>indexMs: 0</code>; the cold condition includes provider indexing. A target cannot pass unless all live runs pass the quality gate.</p><h2 id="measurements" tabindex="-1">Measurements <a class="header-anchor" href="#measurements" aria-label="Permalink to &quot;Measurements&quot;">​</a></h2><p>Each report contains:</p><ul><li>review wall time, total model work, configured concurrency, and maximum active model calls;</li><li>publication duration;</li><li>per-file queue wait and model duration;</li><li>process startup and time to first streamed model text when available;</li><li>prompt and bounded stdout/stderr byte counts;</li><li>estimated input and output tokens;</li><li>output truncation state;</li><li>warm and cold index timing distributions;</li><li>omissions, invalid records, rejected candidates, findings, coverage, and publication status.</li></ul><p>The four-characters-per-token values are estimates. Actual token counts and cost remain <code>null</code> until a harness exposes bounded provider usage metadata.</p><p>Reports never contain prompts, source text, model responses, raw reasoning, credentials, or publication tokens.</p><h2 id="timing-boundaries" tabindex="-1">Timing boundaries <a class="header-anchor" href="#timing-boundaries" aria-label="Permalink to &quot;Timing boundaries&quot;">​</a></h2><p>The checked-in index profile uses bounded timings from named production runs. Live corpus runs combine their measured review wall time with those fixed production samples, including sampled production publication latency. The locally measured publication duration is reported for each run but is not added to the end-to-end totals. The report states this limitation explicitly. Issue #153 owns the broader CGC/GitNexus value and latency comparison.</p><p>Publication uses the production forge-neutral service with an in-memory publisher. It measures validation, rendering, planning, and orchestration, but not GitHub network latency.</p>`,26)])])}const m=i(n,[["render",r]]);export{u as __pageData,m as default};
